// engine/src/schema.js — fresh vault schema and upgrades of older vaults.
// schema.sql (generated by engine/build.js from the real initDatabase() + every migration)
// creates a fresh vault, schema_migrations rows included. A vault saved by an older app
// version is brought up to date on open: missing tables are created from schema.sql, then
// pending migrations run (the same files the server runs, bundled at build time — they
// are idempotent), then missing indexes / triggers are added.
'use strict';

const SCHEMA_SQL = require('../schema.sql');
const MIGRATIONS = require('finman-engine:migrations'); // [{ file, mod }] in lib/migrate.js order
const { columnExists } = require('./columnExists');

function statements(sql) {
  // schema.sql is written one statement per block, separated by a line holding only ';;'.
  return sql.split(/\n;;\n/).map((s) => s.trim()).filter(Boolean);
}

function freshSchema(sqlDb) {
  sqlDb.exec(SCHEMA_SQL.replace(/\n;;\n/g, '\n'));
}

async function upgrade(sqlDb, helpers) {
  const stmts = statements(SCHEMA_SQL);
  const tables = stmts.filter((s) => /^CREATE (VIRTUAL )?TABLE/i.test(s));
  const others = stmts.filter((s) => /^CREATE (UNIQUE )?INDEX|^CREATE TRIGGER|^CREATE VIEW/i.test(s));
  for (const s of tables) {
    try { sqlDb.exec(s); } catch (_) { /* exists in another shape: migrations handle it */ }
  }
  await helpers.run(`CREATE TABLE IF NOT EXISTS schema_migrations (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT UNIQUE NOT NULL,
      applied_at DATETIME DEFAULT CURRENT_TIMESTAMP)`);
  const applied = new Set((await helpers.query('SELECT name FROM schema_migrations')).map((r) => r.name));
  const ran = [];
  for (const { file, mod } of MIGRATIONS) {
    const name = mod.name || file;
    if (applied.has(name)) continue;
    await helpers.transaction(async () => {
      await mod.up(helpers, { columnExists });
      await helpers.run('INSERT OR IGNORE INTO schema_migrations (name) VALUES (?)', [name]);
    });
    ran.push(name);
  }
  for (const s of others) {
    try { sqlDb.exec(s); } catch (_) { /* column not there in this vault: skip */ }
  }
  return ran;
}

module.exports = { SCHEMA_SQL, freshSchema, upgrade, statements };
